/**
 * Map a master WebP path to a prebuilt responsive variant on disk.
 *
 * Vercel Image Optimization is disabled (`images.unoptimized`). These files are
 * generated by `scripts/optimize-images.mjs` and served as static assets only.
 */
export type StaticImageWidth = 64 | 128 | 256 | 384 | 640;

const VARIANT_RE = /-\d+\.webp$/;

export function sizedWebp(src: string, width: StaticImageWidth): string {
  if (!src.endsWith(".webp")) return src;
  const master = VARIANT_RE.test(src) ? src.replace(VARIANT_RE, ".webp") : src;
  return master.replace(/\.webp$/, `-${width}.webp`);
}
